/* Interactive billing console prototype. Cloud Console Billing documentation informed
   the report filters, cost table, cost breakdown, and budget report navigation.
   Sample data only; no Cloud Console API, payment, or messaging connections. */
const consolePages={home:'Welcome',overview:'Overview',budgets:'Budgets & alerts',reports:'Reports',costtable:'Cost table',breakdown:'Cost breakdown',incentives:'Incentives',export:'Billing export',anomalies:'Anomalies',finops:'FinOps hub',commitments:'Committed use discounts',cud:'CUD analysis',pricing:'Pricing',estimator:'Cost estimation',credits:'Credits',invoices:'Invoices',transactions:'Transactions',paymentsettings:'Payment settings',methods:'Payment method',account:'Account management',releases:'Release Notes',search:'Search results',preferences:'Preferences',support:'Help & support'};
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const loadDemo=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('mpsConsole:'+key))??fallback}catch{return fallback}};
const demo={accountName:loadDemo('accountName','Research Group'),favorites:loadDemo('favorites',[]),commitments:loadDemo('commitments',[]),exports:loadDemo('exports',{}),methods:loadDemo('methods',[{id:'visa1122',label:'Visa ····1122',expires:'01/28',primary:true}]),users:loadDemo('users',[{id:'alex',name:'Alex Morgan',email:'alex@example.com',role:'Billing Account Administrator'},{id:'jordan',name:'Jordan Lee',email:'jordan@example.com',role:'Billing Account Viewer'}]),settings:loadDemo('settings',{business:'Research Group',address:'123 Research Way',city:'Ithaca',postal:'14850',country:'United States',email:'billing@example.com',language:'English',density:'Comfortable',emails:true}),notesRead:loadDemo('notesRead',false),redeemed:loadDemo('redeemed',false),anomalyReviewed:loadDemo('anomalyReviewed',false),estimates:loadDemo('estimates',[])};
function saveDemo(key){localStorage.setItem('mpsConsole:'+key,JSON.stringify(demo[key]))}
const usage=[{project:'Atlas',service:'Compute Engine',sku:'E2 instance core',quantity:1000,unit:'vCPU hours',cost:520},{project:'Atlas',service:'Cloud Storage',sku:'Standard storage',quantity:7109,unit:'GB months',cost:142.18},{project:'Atlas',service:'BigQuery',sku:'Analysis',quantity:12.8,unit:'TiB',cost:80},{project:'Beacon',service:'Compute Engine',sku:'E2 instance core',quantity:403.85,unit:'vCPU hours',cost:210},{project:'Beacon',service:'Cloud Storage',sku:'Standard storage',quantity:4431,unit:'GB months',cost:88.62},{project:'Beacon',service:'Cloud SQL',sku:'Cloud SQL instance',quantity:200,unit:'hours',cost:100}];
const priceList=[{service:'Compute Engine',sku:'E2 instance core',rate:.52,unit:'vCPU hour'},{service:'Cloud Storage',sku:'Standard storage',rate:.02,unit:'GB month'},{service:'BigQuery',sku:'Analysis',rate:6.25,unit:'TiB'},{service:'Cloud SQL',sku:'Cloud SQL instance',rate:.5,unit:'hour'},{service:'Cloud Run',sku:'CPU allocation',rate:.0864,unit:'vCPU hour'}];
let reportBudget=null;let reportFilters={period:'current',project:'all',service:'all',group:'service',chart:'bar',credits:true};let consoleSearch='';let modalOrigin=null;let pinnedScroll=0;const previousOverview=overview;const previousRender=render;const previousNav=nav;let navMenu=null;
const action=(name,label,primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${name}" ${extra}>${label}</button>`;
const gotoButton=(route,label)=>`<button class="link" data-page="${route}">${label}</button>`;
function table(headers,rows,caption=''){return `<div class="data-table"><table>${caption?`<caption>${caption}</caption>`:''}<thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="table-empty">No matching results.</td></tr>`}</tbody></table></div>`}
function metric(title,value,description=''){return `<div class="card metric-card"><p>${title}</p><strong>${value}</strong><small>${description}</small></div>`}
function toolbar(description,buttons=''){return `<div class="page-toolbar"><p>${description}</p><div>${buttons}</div></div>`}
function selectControl(key,title,options,value){return `<label class="console-select">${title}<select data-filter="${key}">${options.map(([v,text])=>`<option value="${v}" ${value===v?'selected':''}>${text}</option>`).join('')}</select></label>`}
function filteredUsage(){let rows=usage.filter(r=>(reportFilters.project==='all'||r.project===reportFilters.project)&&(reportFilters.service==='all'||r.service===reportFilters.service));if(reportBudget){if(reportBudget.projects?.length)rows=rows.filter(r=>reportBudget.projects.map(p=>p==='Test Project'?'Beacon':p).includes(r.project));if(reportBudget.services?.length&&!reportBudget.services.includes('All services'))rows=rows.filter(r=>reportBudget.services.includes(r.service))}const scale={current:1,previous:.82,quarter:2.76}[reportFilters.period]||1;return rows.map(r=>({...r,cost:Math.round(r.cost*scale*100)/100,quantity:r.quantity*scale}))}
function reportFilterBar(){return `<div class="filter-bar">${selectControl('period','Time range',[['current','This month'],['previous','Last month'],['quarter','This quarter']],reportFilters.period)}${selectControl('project','Projects',[['all','All projects'],['Atlas','Atlas'],['Beacon','Beacon']],reportFilters.project)}${selectControl('service','Services',[['all','All services'],...priceList.map(r=>[r.service,r.service])],reportFilters.service)}${selectControl('group','Group by',[['service','Service'],['project','Project']],reportFilters.group)}${action('reset-filters','RESET')}</div>`}
function groupedUsage(){const groups={};for(const r of filteredUsage()){const key=r[reportFilters.group];groups[key]=(groups[key]||0)+r.cost}return Object.entries(groups)}
function reportsPage(){const rows=filteredUsage(),total=rows.reduce((s,r)=>s+r.cost,0);const groups=groupedUsage();const credit=total/1140.8*68.45;const target=reportBudget?Number(String(reportBudget.amount).replace(/[$,]/g,'')):null;return toolbar('Analyze costs and usage for your billing account.',action('download-costs','DOWNLOAD CSV')+action('save-report','SAVE REPORT')+action('load-report','OPEN SAVED REPORT'))+(reportBudget?`<div class="info-banner">Budget scope: ${esc(reportBudget.name||'Unsaved budget')} ${target?` · Budget ${money(target)}`:''} ${action('clear-budget-scope','CLEAR BUDGET SCOPE')}</div>`:'')+reportFilterBar()+`<div class="metrics-grid">${metric('Cost',money(total),'Usage cost before credits')}${metric('Forecast',money(total*1.36),'Illustrative month end forecast')}${metric('Credits',reportFilters.credits?money(-credit):money(0),'Discounts and promotional credits')}</div><section class="card"><div class="chart-heading"><h2>Cost by ${reportFilters.group}</h2>${selectControl('chart','Chart style',[['bar','Bar'],['line','Trend']],reportFilters.chart)}</div><div class="report-chart ${reportFilters.chart==='line'?'trend-view':''}">${groups.length?groups.map(([name,n])=>`<div class="report-series"><span>${esc(name)}</span><div class="report-track"><div style="width:${Math.max(2,n/Math.max(...groups.map(g=>g[1]))*88)}%"></div></div><strong>${money(n)}</strong></div>`).join(''):'<p>No usage matches these filters.</p>'}</div>${target?`<p class="budget-line">Budget amount: ${money(target)}</p>`:''}<label class="check"><input type="checkbox" data-report-credits ${reportFilters.credits?'checked':''}>Include credits in net cost</label></section>${table(['Project','Service','Cost'],rows.map(r=>[esc(r.project),esc(r.service),money(r.cost)]))}<div class="totals">Net cost ${money(total-(reportFilters.credits?credit:0))}</div>`}
function costTablePage(){const rows=filteredUsage();return toolbar('Detailed usage costs, grouped by project, service, and SKU.',action('download-costs','DOWNLOAD CSV'))+reportFilterBar()+table(['Project','Service','SKU','Usage','Cost'],rows.map(r=>[esc(r.project),esc(r.service),esc(r.sku),`${r.quantity.toLocaleString('en-US',{maximumFractionDigits:2})} ${r.unit}`,money(r.cost)]))+`<div class="totals">Total ${money(rows.reduce((s,r)=>s+r.cost,0))}</div>`}
function breakdownPage(){return toolbar('Understand your monthly costs and savings.',action('download-breakdown','DOWNLOAD CSV'))+selectControl('period','Time range',[['current','This month'],['previous','Last month'],['quarter','This quarter']],reportFilters.period)+`<section class="card breakdown"><h2>Cost breakdown</h2>${[['Usage cost',1140.8,'cost'],['Discount credits',-48.45,'saving'],['Promotional credits',-20,'saving'],['Subtotal',1072.35,'cost'],['Tax',0,'cost'],['Total',1072.35,'total']].map(([label,n,kind])=>`<div class="breakdown-row"><span>${label}</span><div class="breakdown-track"><div class="${kind}" style="width:${Math.max(3,Math.abs(n)*({previous:.82,quarter:2.76}[reportFilters.period]||1)/3200*95)}%"></div></div><strong>${money(n*({previous:.82,quarter:2.76}[reportFilters.period]||1))}</strong></div>`).join('')}</section>`}
function incentivesPage(){return toolbar('Review offers available to this sample billing account.',action('redeem','REDEEM CODE',true))+`<div class="overviewgrid"><section class="card"><span class="status">${demo.redeemed?'Applied':'Available'}</span><h2>Research cloud credit</h2><p>Apply the sample code RESEARCH100 to add a $100 credit to this prototype.</p>${action('redeem',demo.redeemed?'VIEW CREDIT':'REDEEM OFFER',true)}</section><section class="card"><h2>Committed use savings</h2><p>Explore commitments for predictable compute workloads.</p>${gotoButton('commitments','VIEW COMMITTED USE DISCOUNTS')}</section></div>`}
function exportPage(){return toolbar('Configure a sample billing data export destination.',action('configure-export','EDIT SETTINGS',true))+`<div class="tabs"><button class="selected" data-action="export-tab">BIGQUERY EXPORT</button><button data-action="download-costs">DOWNLOAD CSV</button></div>${table(['Export type','Status','Project','Dataset','Action'],['Standard usage cost','Detailed usage cost','Pricing'].map((type,i)=>[type,demo.exports.dataset?'<span class="status">Enabled</span>':'Not configured',esc(demo.exports.project||'—'),esc(demo.exports.dataset||'—'),action('configure-export','CONFIGURE',false,`data-export-type="${i}"`)]))}<p class="page-note">Exports are simulated and saved in this browser.</p>`}
function anomaliesPage(){return toolbar('Review unexpected changes in sample costs.',action('anomaly-preferences','MANAGE ALERTS'))+table(['Detected','Project','Service','Cost impact','Status',''],[['Oct 21, 2026','Atlas','Compute Engine','+$42.80',demo.anomalyReviewed?'Reviewed':'Needs review',action('anomaly-details','VIEW DETAILS')]])}
function finopsPage(){return toolbar('Identify opportunities to manage and optimize cloud costs.',gotoButton('reports','VIEW REPORTS'))+`<div class="metrics-grid">${metric('Estimated monthly savings','$86.40','Illustrative recommendations')}${metric('Optimization score','72 / 100','Sample account score')}${metric('Active projects','2','Atlas and Beacon')}</div><div class="overviewgrid"><section class="card"><h2>Rightsize idle compute</h2><p>One sample Atlas instance is underutilized. Estimated savings: $36.40 per month.</p>${action('recommendation','REVIEW RECOMMENDATION')}</section><section class="card"><h2>Plan predictable usage</h2><p>Explore committed use discounts for stable workloads.</p>${gotoButton('commitments','VIEW COMMITMENTS')}</section></div>`}
function commitmentsPage(){return toolbar('Manage sample commitments for predictable resource usage.',action('new-commitment','CREATE COMMITMENT',true))+table(['Name','Service','Term','Monthly commitment','Status',''],demo.commitments.map(c=>[esc(c.name),esc(c.service),esc(c.term),money(c.amount),'<span class="status">Simulated</span>',action('commitment-details','DETAILS',false,`data-id="${c.id}"`)]))+`<p class="page-note">Creating a commitment here does not purchase Cloud Console resources.</p>`}
function cudPage(){const total=demo.commitments.reduce((s,c)=>s+Number(c.amount),0);return toolbar('Compare committed capacity and covered usage.',gotoButton('commitments','MANAGE COMMITMENTS'))+`<div class="metrics-grid">${metric('Monthly commitment',money(total),'Saved sample commitments')}${metric('Utilization',total?'84%':'0%','Illustrative covered usage')}${metric('Estimated savings',money(total*.17),'Sample 17% savings model')}</div>${table(['Metric','Value'],[['Eligible Compute Engine usage',money(730)],['Committed monthly capacity',money(total)],['Uncovered usage',money(Math.max(0,730-total*.84))]])}`}
function pricingPage(){const q=consoleSearch.toLowerCase();return toolbar('Illustrative unit prices for the services used in this prototype.',action('download-pricing','DOWNLOAD CSV'))+`<label class="table-search">Filter services or SKUs<input data-table-search placeholder="Search pricing" value="${esc(consoleSearch)}"></label>`+table(['Service','SKU','Unit price','Unit',''],priceList.filter(r=>(r.service+' '+r.sku).toLowerCase().includes(q)).map((r)=>[r.service,r.sku,money(r.rate),r.unit,action('estimate-service','ESTIMATE',false,`data-service="${r.service}"`)]))+`<p class="page-note">Sample prices for interaction testing. Actual pricing varies by region and usage.</p>`}
function estimatorPage(){const total=demo.estimates.reduce((s,r)=>s+r.quantity*priceList.find(p=>p.service===r.service).rate,0);return toolbar('Build and adjust a sample monthly cost estimate.',action('add-estimate','ADD SERVICE',true)+action('download-estimate','DOWNLOAD ESTIMATE'))+table(['Service','Estimated usage','Unit price','Monthly estimate',''],demo.estimates.map(r=>{const p=priceList.find(p=>p.service===r.service);return [p.service,`${r.quantity} ${p.unit}s`,money(p.rate),money(r.quantity*p.rate),action('edit-estimate','EDIT',false,`data-id="${r.id}"`)+action('remove-estimate','REMOVE',false,`data-id="${r.id}"`)]}))+`<div class="totals">Estimated monthly cost ${money(total)}</div>`}
function creditsPage(){return toolbar('Track applied and remaining sample credits.',gotoButton('incentives','VIEW INCENTIVES'))+table(['Credit','Original amount','Used','Remaining','Status'],[['Promotional credit',money(100),money(20),money(80),'Active'],...(demo.redeemed?[['Research cloud credit',money(100),money(0),money(100),'Active']]:[])])}
const invoiceRows=[{id:'INV-2026-09',period:'September 2026',amount:927.4,status:'Paid'},{id:'INV-2026-08',period:'August 2026',amount:864.2,status:'Paid'},{id:'INV-2026-07',period:'July 2026',amount:802.15,status:'Paid'}];
function invoicesPage(){return toolbar('View sample invoices and download their details.',action('download-invoices','DOWNLOAD LIST'))+table(['Invoice','Period','Amount','Status',''],invoiceRows.map(r=>[r.id,r.period,money(r.amount),'<span class="status">'+r.status+'</span>',action('invoice-details','VIEW',false,`data-id="${r.id}"`)+action('download-invoice','DOWNLOAD',false,`data-id="${r.id}"`)]))}
function transactionsPage(){return toolbar('Review sample charges and payments.',action('download-transactions','DOWNLOAD CSV'))+table(['Date','Description','Type','Amount'],invoiceRows.flatMap((r,i)=>[[`2026-${String(10-i).padStart(2,'0')}-01`,r.id+' · Usage charges','Charge',money(r.amount)],[`2026-${String(10-i).padStart(2,'0')}-02`,'Visa ····1122','Payment',money(-r.amount)]]))}
function paymentSettingsPage(){const s=demo.settings;return toolbar('Manage the sample payments profile and billing notifications.',action('edit-settings','EDIT SETTINGS',true))+`<div class="overviewgrid"><section class="card"><h2>Payments profile</h2><p>${esc(s.business)}</p><p>${esc(s.address)}<br>${esc(s.city)} ${esc(s.postal)}<br>${esc(s.country)}</p><p>Profile type: Business</p></section><section class="card"><h2>Billing contacts</h2><p>${esc(s.email)}</p><p>Email notifications: ${s.emails?'Enabled':'Disabled'}</p>${gotoButton('account','MANAGE ACCOUNT USERS')}</section></div>`}
function methodsPage(){return toolbar('Manage payment methods for this prototype.',action('add-method','ADD SAMPLE PAYMENT METHOD',true))+`<div class="overviewgrid">${demo.methods.map(m=>`<section class="card"><span class="status">${m.primary?'Primary':'Backup'}</span><h2>${esc(m.label)}</h2><p>Expires ${esc(m.expires)}</p><div class="buttons">${m.primary?'':action('primary-method','SET AS PRIMARY',false,`data-id="${m.id}"`)}${action('remove-method','REMOVE',false,`data-id="${m.id}"`)}</div></section>`).join('')}</div><p class="page-note">Only sample cards are available. No real payment details are collected.</p>`}
function accountPage(){return toolbar('Manage the billing account and sample user roles.',action('rename-account','RENAME ACCOUNT')+action('add-user','ADD SAMPLE USER',true))+`<section class="card"><h2>${esc(demo.accountName)}</h2><p>Billing account ID: 000000-000000-000000</p><span class="status">Active</span></section>`+table(['User','Email','Role',''],demo.users.map(u=>[esc(u.name),esc(u.email),esc(u.role),action('edit-user','EDIT ROLE',false,`data-id="${u.id}"`)+action('remove-user','REMOVE',false,`data-id="${u.id}"`)]))+`<p class="page-note">Changes affect this prototype only. No invitations are sent.</p>`}
function releasesPage(){return `<section class="card release-list"><h2>October 22, 2026</h2><p>All billing navigation destinations now open interactive sample pages.</p><p>Reports include project, service, and time filters, with CSV downloads.</p><p>Budget thresholds support 10% through 100%. Help descriptions and Overview as the default page are included.</p>${gotoButton('overview','BACK TO OVERVIEW')}</section>`}
function searchPage(){const q=consoleSearch.toLowerCase();const results=Object.entries(consolePages).filter(([id,name])=>id!=='search'&&name.toLowerCase().includes(q));return toolbar(`Results for “${esc(consoleSearch)}”`)+`<div class="search-results">${results.length?results.map(([id,name])=>`<button class="search-result" data-page="${id}"><strong>${name}</strong><small>Billing / ${name}</small><span>→</span></button>`).join(''):'<section class="card"><h2>No matching pages</h2><p>Try “budget”, “cost”, “payment”, or “report”.</p></section>'}</div>`}
function preferencesPage(){return toolbar('Customize your prototype console.',action('preferences-dialog','EDIT PREFERENCES',true))+table(['Preference','Current value'],[['Language',esc(demo.settings.language)],['Display density',esc(demo.settings.density)],['Billing email notifications',demo.settings.emails?'Enabled':'Disabled']])}
function supportPage(){return `<section class="card"><h2>Cloud Billing help</h2><p>Explore billing reports, manage a budget, or review the official documentation.</p><div class="buttons">${gotoButton('reports','BILLING REPORTS')}${gotoButton('budgets','BUDGETS & ALERTS')}<a class="btn" href="https://docs.cloud.google.com/billing/docs" target="_blank" rel="noopener">OPEN BILLING DOCUMENTATION</a></div></section><section class="card" style="margin-top:20px"><h2>Prototype support</h2><p>This site uses illustrative data stored in your browser. It does not connect to a Cloud Console account or process payments.</p></section>`}
overview=function(){let html=previousOverview().replaceAll('Research Group',esc(demo.accountName));if(tab==='payment'){const primary=demo.methods.find(m=>m.primary);html=html.replace('Visa ····1122',esc(primary?.label||'No payment method')).replace('Expires 01/23',primary?'Expires '+esc(primary.expires):'Add a sample method');html=html.replace('<h2>Transactions</h2>','<h2>Transactions</h2>'+gotoButton('transactions','VIEW TRANSACTIONS')).replace('<h2>How you pay</h2>','<h2>How you pay</h2>'+gotoButton('methods','MANAGE PAYMENT METHODS')).replace('<h2>Settings</h2>','<h2>Settings</h2>'+gotoButton('paymentsettings','MANAGE SETTINGS'));html+=`<div class="buttons">${action('payment-dialog','MAKE A SAMPLE PAYMENT')}${gotoButton('invoices','VIEW INVOICES')}</div>`}return html};
const cloudMark='<span class="mps-mark" aria-hidden="true">C</span>';
const homeProducts=[['APIs & Services','api'],['IAM & Admin','iam'],['Billing','billing'],['Compute Engine','compute'],['Cloud Storage','storage'],['BigQuery','bigquery'],['VPC network','network'],['Kubernetes Engine','kubernetes']];
function productIcon(type){const paths={api:'M3 7h3v10H3m7-10h3v10h-3m7-10h4v10h-4',iam:'M12 3l8 4v6c0 5-8 8-8 8s-8-3-8-8V7z',billing:'M3 6h18v12H3zM3 10h18M6 15h5',compute:'M6 6h12v12H6zM9 9h6v6H9M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4',storage:'M3 5h18v5H3zM3 14h18v5H3zM6 7h1m-1 9h1',bigquery:'M16 16l6 6M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0M6 11V8m4 6V6m4 5V8',network:'M3 4h6v6H3zM15 14h6v6h-6zM6 10v7h9M9 7h9v7',kubernetes:'M12 2l9 5v10l-9 5-9-5V7zM12 7l5 3v5l-5 3-5-3v-5z'};return `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" aria-hidden="true"><path d="${paths[type]||paths.compute}"/></svg>`}
function cloudHome(){return `<div class="mps-home"><section class="mps-hero"><div class="hero-decoration" aria-hidden="true"><span></span><span></span><svg viewBox="0 0 140 160"><path d="M20 80h100L55 15v130l65-65M20 80l35-35" fill="none" stroke="currentColor" stroke-width="2"/><path d="M55 145l65-65" stroke="currentColor" stroke-dasharray="2 4"/></svg></div><h1>${cloudMark}<span>Welcome, Alex Kim</span></h1><div class="mps-hero-cards"><section class="mps-trial"><div class="trial-summary"><h2>You're in Free Trial</h2><div class="trial-summary-body"><div class="credit-ring" aria-label="0 percent of trial credits used"><span aria-hidden="true">♧</span></div><div><p class="credit-amount">$0 of $300 credits used</p><p class="trial-expiry">90 days remaining</p><button class="text-link" data-action="mps-trial-info">What happens when my trial ends?</button><button class="btn primary upgrade-button" data-action="mps-upgrade">Upgrade</button></div></div></div><div class="trial-project"><p class="working-project">You're working on project <button data-action="home-project">Atlas</button></p><div class="project-identifiers"><span>ID: <strong>atlas-research-demo</strong></span><button data-action="home-project-info" aria-label="View project ID">▣</button></div><div class="project-links"><button class="text-link" data-page="iam">Add people to your project</button><button class="text-link" data-page="overview">Set up budget alerts</button><button class="text-link" data-page="reports">Review product spend</button><button class="text-link" data-action="mps-credit-info">What your credits cover ↗</button></div></div></section><section class="mps-assistant-card"><span class="assistant-spark" aria-hidden="true">✧</span><h2>Try Console Assist chat</h2><p>Explore resources and get help with your cloud projects.</p><button data-action="mps-assistant">Chat now <span aria-hidden="true">→</span></button></section></div></section><section class="mps-home-body"><div class="gcp-actions mps-home-actions"><button data-action="mps-api-key">＋ Create API key</button><button data-action="mps-create-agent">＋ Create an agent</button><button data-action="home-product" data-product="compute">＋ Create a VM</button><button data-action="home-product" data-product="bigquery">＋ Run a query in BigQuery</button><button data-action="mps-deploy">＋ Deploy an application</button><button data-action="home-product" data-product="storage">＋ Create a storage bucket</button></div><div class="mps-recommend-heading"><h2>See recommendations based on your interests in</h2><select aria-label="Recommendation interests" data-mps-interest><option>Data, Agents, and AI/ML</option><option>Infrastructure and security</option><option>Cost management</option></select></div><h3>Products</h3><section class="mps-recommend-card"><span class="recommend-star" aria-hidden="true">☆</span><div><h2>Avoid missing out on critical notifications</h2><p>Assign project contacts to receive updates about security, billing, and your cloud resources.</p><button class="text-link" data-page="iam">Manage project contacts</button></div></section><h3>Quick access</h3><div class="gcp-quick">${homeProducts.map(([label,type])=>`<button class="gcp-tile" ${type==='billing'?'data-page="overview"':`data-action="home-product" data-product="${type}"`}><span class="tile-project">Atlas</span><span class="tile-product">${productIcon(type)}${label}</span></button>`).join('')}</div><div class="mps-home-links"><button class="all-products" data-action="home-all-products">▦ View all products</button><button class="text-link" data-action="home-dashboard">Dashboard</button><button class="text-link" data-action="home-recommendations">Recommendations</button></div></section></div>`}


nav=function(){const el=$('#nav');const scroll=el.scrollTop;previousNav();if(page==='home'){el.innerHTML=`<p class="crumb">Cloud Console</p><nav><button class="home-nav active" data-page="home">⌂ <span>Home</span></button><button class="home-nav" data-page="overview">▣ <span>Billing</span></button><button class="home-nav" data-page="support">? <span>Help & support</span></button></nav>`}else el.insertAdjacentHTML('afterbegin','<button class="console-home-link" data-page="home">← Console home</button>');const accountButton=el.querySelector('.account');if(accountButton)accountButton.textContent=demo.accountName;const crumb=el.querySelector('.crumb');if(crumb)crumb.textContent=page==='home'?'Cloud Console':'Billing / '+(consolePages[page]||'Budgets & alerts');el.querySelectorAll('[data-page]').forEach(item=>{if(item.dataset.page===page)item.setAttribute('aria-current','page')});el.scrollTop=scroll};
const pageViews={home:cloudHome,reports:reportsPage,costtable:costTablePage,breakdown:breakdownPage,incentives:incentivesPage,export:exportPage,anomalies:anomaliesPage,finops:finopsPage,commitments:commitmentsPage,cud:cudPage,pricing:pricingPage,estimator:estimatorPage,credits:creditsPage,invoices:invoicesPage,transactions:transactionsPage,paymentsettings:paymentSettingsPage,methods:methodsPage,account:accountPage,releases:releasesPage,search:searchPage,preferences:preferencesPage,support:supportPage};
render=function(){document.body.classList.toggle('console-welcome',page==='home');document.body.classList.remove('home-menu-open');$('.brand').textContent='Cloud Console';let selector=$('#homeProjectSelector');if(page==='home'&&!selector){$('.brand').insertAdjacentHTML('afterend','<button id="homeProjectSelector" data-action="home-project">♧ &nbsp; Atlas &nbsp; ▾</button>')}else if(page!=='home'&&selector)selector.remove();if(pageViews[page]){nav();$('#pageTitle').textContent=consolePages[page];$('#content').innerHTML=pageViews[page]()}else previousRender();document.body.classList.toggle('compact',demo.settings.density==='Compact');const badge=$('.notice');if(badge)badge.textContent=demo.notesRead?'0':'1';if(page!=='home'&&page!=='edit'&&page!=='overview'&&page!=='budgets'){const existing=$('#content .sample-note');if(!existing)$('#content').insertAdjacentHTML('afterbegin','<div class="sample-note">Sample billing data · Interactive prototype</div>')}};
function consoleNavigate(route){if(innerWidth<=650)document.body.classList.remove('navclosed');if(!consolePages[route]&&route!=='edit')route='home';page=route;closeFloating();render();if(location.hash.slice(1)!==route)history.pushState({page:route},'',`#${route}`);window.scrollTo(0,0)}
window.addEventListener('popstate',()=>{const route=location.hash.slice(1);page=consolePages[route]?route:'home';closeFloating();render()});
function closeFloating(){document.querySelectorAll('.floating-menu').forEach(el=>el.remove())}
function showMenu(anchor,contents){closeFloating();const menu=document.createElement('div');menu.className='floating-menu';menu.setAttribute('role','dialog');menu.setAttribute('aria-label','Console menu');menu.innerHTML=contents;document.body.append(menu);const rect=anchor.getBoundingClientRect();menu.style.top=Math.min(rect.bottom+6,innerHeight-menu.offsetHeight-12)+'px';menu.style.left=Math.max(12,Math.min(rect.left,innerWidth-menu.offsetWidth-12))+'px';menu.querySelector('button,a')?.focus()}
function openNavMenu(name){const target=navItems.find(item=>item[0]===name)?.[2];const anchor=[...document.querySelectorAll('[data-favorite]')].find(b=>b.dataset.favorite===name);showMenu(anchor,`<h3>${esc(name)}</h3><button data-page="${target}">Open page</button><button data-action="toggle-favorite" data-name="${esc(name)}">${demo.favorites.includes(name)?'Remove from':'Add to'} favorites</button>`)}
function dialog(title,contents,buttons=''){closeFloating();modalOrigin=document.activeElement;$('#overlay').innerHTML=`<div class="modal console-modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="dialog-heading"><h2>${title}</h2><button class="icon-button" data-action="dismiss" aria-label="Close dialog">×</button></div>${contents}${buttons?`<div class="buttons">${buttons}</div>`:''}</div>`;$('#overlay').querySelector('input,select,button')?.focus()}
function dismiss(){const el=$('#overlay');el.innerHTML='';modalOrigin?.isConnected&&modalOrigin.focus()}
function formInput(name,title,value='',type='text',extra=''){return `<label class="form-input">${title}<input name="${name}" type="${type}" value="${esc(value)}" required ${extra}></label>`}
function formSelect(name,title,options,value){return `<label class="form-input">${title}<select name="${name}">${options.map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select></label>`}
function formDialog(title,type,fields,id=''){dialog(title,`<form data-console-form="${type}" data-id="${id}">${fields}<p class="form-error" role="alert"></p><div class="buttons"><button class="btn primary" type="submit">SAVE</button><button class="btn" type="button" data-action="dismiss">CANCEL</button></div></form>`)}
function downloadFile(name,text,type='text/csv;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download prepared')}
function csv(rows){return rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')}
function downloadCosts(){const rows=filteredUsage();downloadFile('billing-costs.csv',csv([['Project','Service','SKU','Quantity','Unit','Cost (USD)'],...rows.map(r=>[r.project,r.service,r.sku,r.quantity,r.unit,r.cost.toFixed(2)])]))}
function executeConsoleAction(name,t){
 if(typeof handleCloudAction==='function'&&handleCloudAction(name,t))return;
 if(name==='home-project'){dialog('Select a project','<p class="page-note">Recent projects</p><button class="account-option" data-action="dismiss"><strong>Atlas</strong><small>atlas-research · Research Group</small><span class="status">Selected</span></button>');return}
 if(name==='home-project-info'){dialog('Project info','<p><strong>Project name:</strong> Atlas</p><p><strong>Project number:</strong> 233984005590</p><p><strong>Project ID:</strong> atlas-research</p>',action('dismiss','CLOSE'));return}
 if(name==='home-quick-info'){dialog('Quick access','<p>Quick access brings your frequently used Cloud Console products together.</p><p>Select Billing to manage the Research Group billing account.</p>',action('dismiss','GOT IT'));return}
 if(name==='home-all-products'){dialog('All products',`<div class="all-product-list">${homeProducts.map(([label,type])=>`<button ${type==='billing'?'data-page="overview"':`data-action="home-product" data-product="${type}"`}>${productIcon(type)}${label}<span>→</span></button>`).join('')}</div>`);return}
 if(name==='home-product'){const item=homeProducts.find(p=>p[1]===t.dataset.product);dialog(item?.[0]||'Cloud Console',`<p>Project: Atlas</p><p>This billing workflow prototype includes the Billing experience. Manage costs and budget alerts for this project's cloud resources in Billing.</p>`,gotoButton('overview','GO TO BILLING')+action('dismiss','CLOSE'));return}
 if(name==='home-dashboard'){dialog('Project dashboard','<p><strong>Atlas</strong></p><p>Project ID: atlas-research</p><p>Billing account: Research Group</p><span class="status">Active</span>',gotoButton('overview','VIEW BILLING')+action('dismiss','CLOSE'));return}
 if(name==='home-recommendations'){dialog('Recommendations','<p>Create a budget alert to monitor costs for Atlas.</p>',gotoButton('budgets','MANAGE BUDGETS')+action('dismiss','CLOSE'));return}
 if(name==='home-privacy'||name==='home-terms'){dialog(name==='home-privacy'?'Privacy Policy':'Terms of Service','<p>This is an interactive research prototype. Budget settings are stored in your browser.</p>',action('dismiss','CLOSE'));return}

 if(name==='preview-owners'){
 const rule=draft.rules.find(r=>Number(r.percent)===90)||draft.rules[0]||{percent:90,trigger:'Actual'};
 const percent=Number(rule.percent),budgetAmount=amount(),budgetName=draft.name||draft.projects[0]||'Atlas';
 dialog('Email alert preview',`<article class="email-alert-preview"><div class="email-meta"><div><strong>From:</strong> Cloud Billing</div><div><strong>Subject:</strong> Budget alert: ${esc(percent)}% threshold reached</div></div><h3>Budget alert</h3><p>Your budget ${esc(budgetName)} has ${rule.trigger==='Forecasted'?'been forecast to reach':'reached'} <strong>${esc(percent)}%</strong> of its configured amount.</p><div class="email-totals"><div><strong>Budget:</strong> ${money(budgetAmount)}</div><div><strong>${rule.trigger==='Forecasted'?'Forecasted':'Current'} spending:</strong> ${money(budgetAmount*percent/100)}</div></div><button class="email-report" data-action="preview-owner-report"><span aria-hidden="true">→</span> View report</button></article>`);
 $('#overlay .modal').classList.add('email-preview-modal');return
 }
 if(name==='preview-owner-report'){dismiss();go('reports');return}
 if(name==='dismiss'){dismiss();return}
 if(name==='collapse-nav'){document.body.classList.toggle('navclosed');return}
 if(name==='search'){consoleSearch=$('.search input').value.trim();go('search');return}
 if(name==='account-picker'){dialog('Select a billing account',`<button class="account-option" data-action="select-account"><strong>${esc(demo.accountName)}</strong><small>000000-000000-000000</small><span class="status">Active</span></button><p class="page-note">One sample billing account is available.</p>`,gotoButton('account','MANAGE BILLING ACCOUNT'));return}
 if(name==='select-account'){dismiss();go('overview');return}
 if(name==='assistant'){dialog('Billing assistant',`<p>Explore costs, set a budget, or manage this sample account.</p><div class="assistant-options">${gotoButton('reports','How much am I spending?')}${gotoButton('budgets','How do I create a budget?')}${gotoButton('finops','Where can I save money?')}${gotoButton('support','Where can I find billing help?')}</div><form data-console-form="assistant"><label class="form-input">Ask about billing<input name="question" placeholder="For example: How do I set an alert?" required></label><button class="btn primary">ASK</button><div id="assistantReply" role="status"></div></form>`);return}
 if(name==='shell'){dialog('Cloud Shell',`<p class="page-note">Simulated shell. No commands run against a real account.</p><pre class="shell-output" id="shellOutput">Welcome to the billing demo shell.\nType help to see available commands.</pre><form data-console-form="shell"><label class="form-input">Command<input name="command" placeholder="help" autocomplete="off" required></label><button class="btn primary">RUN</button></form>`);return}
 if(name==='notifications'){showMenu(t,`<h3>Notifications</h3><p>${demo.notesRead?'All caught up.':'Billing account ready. Create your first budget to monitor spending.'}</p><button data-page="budgets">Open Budgets & alerts</button><button data-action="mark-read">Mark all as read</button>`);return}
 if(name==='mark-read'){demo.notesRead=true;saveDemo('notesRead');closeFloating();render();return}
 if(name==='more'){showMenu(t,`<h3>Console options</h3><button data-page="preferences">Preferences</button><button data-page="support">Help & support</button><button data-page="releases">Release Notes</button><button data-action="favorites">Favorites</button>`);return}
 if(name==='profile'){showMenu(t,`<h3>Alex Morgan</h3><p>alex@example.com<br>Sample console profile</p><button data-page="account">Manage account</button><button data-page="paymentsettings">Payment settings</button><button data-page="preferences">Preferences</button>`);return}
 if(name==='favorites'){dialog('Favorite pages',demo.favorites.length?demo.favorites.map(n=>{const r=navItems.find(v=>v[0]===n);return `<p>${gotoButton(r[2],esc(n))}</p>`}).join(''):'<p>Use the three dot menu beside a sidebar page to add a favorite.</p>');return}
 if(name==='toggle-favorite'){const n=t.dataset.name;demo.favorites=demo.favorites.includes(n)?demo.favorites.filter(v=>v!==n):[...demo.favorites,n];saveDemo('favorites');closeFloating();toast('Favorites updated');return}
 if(name==='reset-filters'){reportFilters={period:'current',project:'all',service:'all',group:'service',chart:'bar',credits:true};reportBudget=null;render();return}
 if(name==='clear-budget-scope'){reportBudget=null;render();return}
 if(name==='download-costs'){downloadCosts();return}
 if(name==='load-report'){const saved=loadDemo('savedReport',null);if(!saved){dialog('Saved reports','<p>No saved report yet. Configure filters and choose Save report.</p>',action('dismiss','CLOSE'));return}reportFilters={...saved.filters};reportBudget=null;render();toast('Opened '+saved.name);return}
 if(name==='save-report'){formDialog('Save report','save-report',formInput('name','Report name','Monthly cost report'));return}
 if(name==='download-breakdown'){const f={previous:.82,quarter:2.76}[reportFilters.period]||1;downloadFile('cost-breakdown.csv',csv([['Category','Amount (USD)'],['Usage cost',1140.8*f],['Discount credits',-48.45*f],['Promotional credits',-20*f],['Net cost',1072.35*f]]));return}
 if(name==='redeem'){if(demo.redeemed){go('credits');return}formDialog('Redeem sample credit','redeem',`<p>Use RESEARCH100 to try the redemption flow.</p>${formInput('code','Sample code')}`);return}
 if(name==='configure-export'||name==='export-tab'){formDialog('Configure billing export','export',formSelect('project','Project',['Atlas','Beacon'],demo.exports.project||'Atlas')+formInput('dataset','BigQuery dataset',demo.exports.dataset||'billing_export','text','pattern="[A-Za-z_][A-Za-z0-9_]*"')+'<p class="page-note">This saves sample settings only.</p>');return}
 if(name==='anomaly-preferences'){formDialog('Anomaly alert preferences','anomaly-preferences',formInput('email','Alert email',demo.settings.email,'email'));return}
 if(name==='anomaly-details'){dialog('Cost anomaly: Atlas',`<p>Compute Engine spending was $42.80 higher than the illustrative daily baseline on October 21.</p>${table(['Metric','Amount'],[['Expected daily spend','$24.00'],['Observed spend','$66.80'],['Difference','+$42.80']])}`,gotoButton('reports','INVESTIGATE IN REPORTS')+action('review-anomaly','MARK AS REVIEWED',true));return}
 if(name==='review-anomaly'){demo.anomalyReviewed=true;saveDemo('anomalyReviewed');dismiss();render();toast('Anomaly marked as reviewed');return}
 if(name==='recommendation'){dialog('Rightsize idle compute',`<p>Sample instance atlas-worker-02 has low average CPU utilization. Reducing its size could save $36.40 per month.</p><p>Review workload requirements before making real infrastructure changes.</p>`,gotoButton('estimator','MODEL ESTIMATED COST')+action('dismiss','CLOSE'));return}
 if(name==='new-commitment'){formDialog('Create sample commitment','commitment',formInput('name','Commitment name')+formSelect('service','Service',['Compute Engine','Cloud SQL'],'Compute Engine')+formSelect('term','Term',['1 year','3 years'],'1 year')+formInput('amount','Monthly commitment (USD)','100','number','min="1" step="0.01"')+'<p class="page-note">Simulation only. No purchase is made.</p>');return}
 if(name==='commitment-details'){const c=demo.commitments.find(v=>v.id===t.dataset.id);dialog('Commitment details',table(['Field','Value'],[['Name',esc(c.name)],['Service',c.service],['Term',c.term],['Monthly amount',money(c.amount)],['Status','Simulated']]),gotoButton('cud','VIEW ANALYSIS')+action('remove-commitment','REMOVE SAMPLE',false,`data-id="${c.id}"`));return}
 if(name==='remove-commitment'){demo.commitments=demo.commitments.filter(c=>c.id!==t.dataset.id);saveDemo('commitments');dismiss();render();return}
 if(name==='download-pricing'){downloadFile('sample-pricing.csv',csv([['Service','SKU','Unit price (USD)','Unit'],...priceList.map(p=>[p.service,p.sku,p.rate,p.unit])]));return}
 if(name==='estimate-service'||name==='add-estimate'||name==='edit-estimate'){const item=demo.estimates.find(r=>r.id===t.dataset.id);formDialog('Estimate service cost','estimate',formSelect('service','Service',priceList.map(p=>p.service),item?.service||t.dataset.service||'Compute Engine')+formInput('quantity','Monthly units',item?.quantity||100,'number','min="0.01" step="0.01"'),item?.id||'');return}
 if(name==='remove-estimate'){demo.estimates=demo.estimates.filter(r=>r.id!==t.dataset.id);saveDemo('estimates');render();return}
 if(name==='download-estimate'){downloadFile('cost-estimate.csv',csv([['Service','Quantity','Monthly cost (USD)'],...demo.estimates.map(r=>[r.service,r.quantity,(r.quantity*priceList.find(p=>p.service===r.service).rate).toFixed(2)])]));return}
 if(name==='download-invoices'){downloadFile('invoices.csv',csv([['Invoice','Period','Amount (USD)','Status'],...invoiceRows.map(r=>[r.id,r.period,r.amount,r.status])]));return}
 if(name==='invoice-details'){const r=invoiceRows.find(r=>r.id===t.dataset.id);dialog(r.id,`<p>${r.period} · Sample invoice</p>${table(['Description','Amount'],[['Cloud usage',money(r.amount)],['Tax','$0.00'],['Total',money(r.amount)],['Status',r.status]])}`,action('download-invoice','DOWNLOAD',true,`data-id="${r.id}"`)+gotoButton('costtable','VIEW COST TABLE'));return}
 if(name==='download-invoice'){const r=invoiceRows.find(r=>r.id===t.dataset.id);downloadFile(r.id+'.csv',csv([['Sample invoice','Period','Amount (USD)','Status'],[r.id,r.period,r.amount,r.status]]));return}
 if(name==='download-transactions'){downloadFile('transactions.csv',csv([['Date','Description','Type','Amount (USD)'],...invoiceRows.flatMap((r,i)=>[[`2026-${String(10-i).padStart(2,'0')}-01`,r.id,'Charge',r.amount],[`2026-${String(10-i).padStart(2,'0')}-02`,'Sample payment','Payment',-r.amount]])]));return}
 if(name==='edit-settings'){const s=demo.settings;formDialog('Edit payments profile','settings',formInput('business','Business name',s.business)+formInput('address','Address',s.address)+formInput('city','City',s.city)+formInput('postal','Postal code',s.postal)+formInput('country','Country',s.country)+formInput('email','Billing email',s.email,'email'));return}
 if(name==='add-method'){formDialog('Add sample payment method','method',formSelect('label','Sample card',['Visa ····4242','Mastercard ····5555'],'Visa ····4242')+formSelect('expires','Expires',['12/28','12/29','12/30'],'12/29')+'<p class="page-note">Choose a sample card. No card number is requested.</p>');return}
 if(name==='primary-method'){demo.methods.forEach(m=>m.primary=m.id===t.dataset.id);saveDemo('methods');render();return}
 if(name==='remove-method'){if(demo.methods.length===1){dialog('Keep a primary method','<p>Add a backup sample method before removing the last payment method.</p>',action('add-method','ADD SAMPLE METHOD',true));return}demo.methods=demo.methods.filter(m=>m.id!==t.dataset.id);if(!demo.methods.some(m=>m.primary))demo.methods[0].primary=true;saveDemo('methods');render();return}
 if(name==='payment-dialog'){dialog('Make a sample payment','<p>No balance is due. Your sample account balance is $0.00.</p>',gotoButton('transactions','VIEW TRANSACTIONS')+action('dismiss','CLOSE'));return}
 if(name==='rename-account'){formDialog('Rename billing account','account-name',formInput('name','Account name',demo.accountName));return}
 if(name==='add-user'||name==='edit-user'){const u=demo.users.find(u=>u.id===t.dataset.id);formDialog(u?'Edit sample user':'Add sample user','user',formInput('name','Name',u?.name||'')+formInput('email','Email',u?.email||'','email')+formSelect('role','Role',['Billing Account Viewer','Billing Account Costs Manager','Billing Account Administrator'],u?.role||'Billing Account Viewer')+'<p class="page-note">No email or invitation will be sent.</p>',u?.id||'');return}
 if(name==='remove-user'){if(demo.users.find(u=>u.id===t.dataset.id)?.role==='Billing Account Administrator'&&demo.users.filter(u=>u.role==='Billing Account Administrator').length===1){dialog('Keep an administrator','<p>Assign another administrator before removing the last administrator.</p>',action('dismiss','CLOSE'));return}demo.users=demo.users.filter(u=>u.id!==t.dataset.id);saveDemo('users');render();return}
 if(name==='preferences-dialog'){formDialog('Console preferences','preferences',formSelect('density','Display density',['Comfortable','Compact'],demo.settings.density)+formSelect('emails','Billing email notifications',['Enabled','Disabled'],demo.settings.emails?'Enabled':'Disabled'));return}
 throw new Error('Unhandled console action: '+name);
}
document.addEventListener('click',e=>{const actionEl=e.target.closest('[data-action]');if(actionEl){e.preventDefault();e.stopImmediatePropagation();executeConsoleAction(actionEl.dataset.action,actionEl);return}const route=e.target.closest('[data-page]');if(route&&e.target.closest('#overlay,.floating-menu')){e.preventDefault();e.stopImmediatePropagation();dismiss();go(route.dataset.page);return}if(!e.target.closest('.floating-menu,[data-favorite]'))closeFloating()},true);
document.addEventListener('change',e=>{if(e.target.dataset.filter){reportFilters[e.target.dataset.filter]=e.target.value;render()}if(e.target.matches('[data-report-credits]')){reportFilters.credits=e.target.checked;render()}});
document.addEventListener('input',e=>{if(e.target.matches('[data-table-search]')){consoleSearch=e.target.value;const start=e.target.selectionStart;render();const input=$('[data-table-search]');input.focus();input.setSelectionRange(start,start)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.search input')){e.preventDefault();executeConsoleAction('search',e.target)}if(e.key==='Escape'){closeFloating()}},true);
document.addEventListener('submit',e=>{const form=e.target.closest('[data-console-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form));for(const k of Object.keys(data))data[k]=data[k].trim();const type=form.getAttribute('data-console-form');const id=form.getAttribute('data-id');const error=message=>{form.querySelector('.form-error').textContent=message};
 if(type==='shell'){const cmd=data.command;const out={help:'Available commands: help, ls, gcloud billing accounts list, clear',ls:'billing-reports/  budgets/  sample-data/', 'gcloud billing accounts list':`ACCOUNT_ID                 NAME                OPEN\n000000-000000-000000        ${demo.accountName}        True`};const output=$('#shellOutput');if(cmd==='clear')output.textContent='';else output.textContent+='\n$ '+cmd+'\n'+(out[cmd]||'Command unavailable in this simulated shell. Type help.');form.reset();return}
 if(type==='assistant'){const q=data.question.toLowerCase();const answer=/budget|alert/.test(q)?'Open Budgets & alerts, choose Create budget, then complete Define, Scope, Amount, and Actions.':/pay|invoice|card/.test(q)?'Use Payment overview to review the balance, or open Invoices and Payment method in the sidebar.':/sav|optim|discount/.test(q)?'Open FinOps hub to review sample savings recommendations and committed use options.':'Open Reports to filter spending by project, service, and time range. Use Download CSV to export the displayed costs.';$('#assistantReply').textContent=answer;return}
 if(type==='save-report'){const saved={name:data.name,filters:reportFilters};localStorage.setItem('mpsConsole:savedReport',JSON.stringify(saved));dismiss();toast('Report saved in this browser');return}
 if(type==='redeem'){if(data.code.toUpperCase()!=='RESEARCH100'){error('Enter the sample code RESEARCH100.');return}demo.redeemed=true;saveDemo('redeemed');dismiss();go('credits');toast('Sample credit applied');return}
 if(type==='export'){demo.exports={project:data.project,dataset:data.dataset};saveDemo('exports')}
 if(type==='anomaly-preferences'){demo.settings.email=data.email;saveDemo('settings')}
 if(type==='commitment'){demo.commitments.push({id:uid(),name:data.name,service:data.service,term:data.term,amount:Number(data.amount)});saveDemo('commitments')}
 if(type==='estimate'){const item={id:id||uid(),service:data.service,quantity:Number(data.quantity)};demo.estimates=id?demo.estimates.map(r=>r.id===id?item:r):[...demo.estimates,item];saveDemo('estimates');page='estimator'}
 if(type==='settings'){Object.assign(demo.settings,data);saveDemo('settings')}
 if(type==='method'){demo.methods.push({id:uid(),label:data.label,expires:data.expires,primary:!demo.methods.length});saveDemo('methods')}
 if(type==='account-name'){demo.accountName=data.name;saveDemo('accountName')}
 if(type==='user'){const existing=demo.users.find(u=>u.id===id);if(existing?.role==='Billing Account Administrator'&&data.role!=='Billing Account Administrator'&&demo.users.filter(u=>u.role==='Billing Account Administrator').length===1){error('Keep at least one Billing Account Administrator.');return}if(demo.users.some(u=>u.email.toLowerCase()===data.email.toLowerCase()&&u.id!==id)){error('This sample user already exists.');return}const user={id:id||uid(),...data};demo.users=id?demo.users.map(u=>u.id===id?user:u):[...demo.users,user];saveDemo('users')}
 if(type==='preferences'){demo.settings.density=data.density;demo.settings.emails=data.emails==='Enabled';saveDemo('settings')}
 dismiss();render();toast('Sample settings saved');
});
const initialRoute=location.hash.slice(1);if(consolePages[initialRoute])page=initialRoute;render();

// Keep keyboard focus in open dialogs and return it when a dialog closes.
document.addEventListener('keydown',e=>{const modal=document.querySelector('#overlay .modal');if(!modal)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();dismiss();return}if(e.key==='Tab'){const nodes=[...modal.querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},true);

document.addEventListener('click',e=>{if(page==='home'&&e.target.closest('#menu')){e.preventDefault();e.stopImmediatePropagation();document.body.classList.toggle('home-menu-open')}},true);
